#!/usr/bin/env python3
"""paths-to-read-site.py [ts|js|calls] [<shift>]: each row has ONE READ SITE of its own, `read$(o)`, which is handed a literal A in plain sight, and a literal B, whose members have the same names in ANOTHER ORDER, OF OTHER KINDS, with one more and one fewer, by ONE ROAD that a flow analysis has to model or to give up on. If the analysis misses the road, the site is compiled for A alone. Untyped JavaScript: every line must be as plain Bun's."""
import sys
ts = len(sys.argv) > 1 and sys.argv[1] == 'ts'
calls = len(sys.argv) > 1 and sys.argv[1] == 'calls'
shift = int(sys.argv[2]) if len(sys.argv) > 2 else 0
import os
lean = bool(os.environ.get('LEAN'))
ROADS = [
 ('directly', 'sink(b)'),
 ('an array literal and an index', 'sink([0, b][1])'), ('push and pop', 'const l = []; l.push(b); sink(l.pop())'), ('unshift and shift', 'const l = []; l.unshift(b); sink(l.shift())'),
 ('splice out', 'const l = [1, b, 2]; sink(l.splice(1, 1)[0])'), ('splice in', 'const l = [1, 2]; l.splice(1, 0, b); sink(l[1])'), ('slice', 'sink([b].slice()[0])'), ('concat', 'sink([].concat([b])[0])'), ('concat of the thing itself', 'sink([].concat(b)[0])'),
 ('flat', 'sink([[b]].flat()[0])'), ('flatMap', 'sink([1].flatMap(() => [b])[0])'), ('fill', 'sink(new Array(2).fill(b)[1])'), ('at', 'sink([b].at(-1))'), ('with', 'sink([0].with(0, b)[0])'), ('toSorted, toReversed, toSpliced', 'sink([b].toSorted()[0]); sink([b].toReversed()[0]); sink([1].toSpliced(0, 1, b)[0])'),
 ('copyWithin', 'const l = [b, 0]; l.copyWithin(1, 0); sink(l[1])'), ('reverse and sort', 'sink([0, b].reverse()[0]); sink([b].sort()[0])'), ('find, findLast', 'sink([1, b].find(x => typeof x === "object")); sink([b, 1].findLast(x => typeof x === "object"))'),
 ('filter', 'sink([1, b].filter(x => typeof x === "object")[0])'), ('map yields it', 'sink([1].map(() => b)[0])'), ('the callback of forEach', '[b].forEach(x => sink(x))'), ('the callback of some, every', '[b].some(x => (sink(x), true)); [b].every(x => (sink(x), true))'),
 ('reduce: the accumulator', 'sink([1].reduce(acc => acc, b))'), ('reduce: the element', '[0, b].reduce((acc, x) => (typeof x === "object" && sink(x), acc))'), ('reduceRight', 'sink([b].reduceRight((acc, x) => x, 0))'), ('the comparer of sort', '[b, b].sort((p, q) => (sink(p), 0))'),
 ('Array.from an array', 'sink(Array.from([b])[0])'), ('Array.from a set', 'sink(Array.from(new Set([b]))[0])'), ('Array.from with a mapper', 'sink(Array.from([1], () => b)[0])'), ('Array.from an array-like', 'sink(Array.from({ length: 1, 0: b })[0])'), ('Array.of', 'sink(Array.of(b)[0])'),
 ('a spread into an array', 'sink([...[b]][0])'), ('a spread of a set', 'sink([...new Set([b])][0])'), ('a spread into a call', 'sink(...[b])'), ('a rest parameter', '((...rest) => sink(rest[0]))(b)'), ('arguments', '(function () { sink(arguments[0]); })(b)'), ('arguments, aliased', '(function (p) { arguments[0] = b; sink(p); }).call(null, 0)' if False else '(function () { const a = arguments; sink(a[a.length - 1]); })(1, b)'),
 ('a pattern over an array', 'const [p] = [b]; sink(p)'), ('a pattern with a default', 'const [p = b] = []; sink(p)'), ('a pattern over an object', 'const { held } = { held: b }; sink(held)'), ('a nested pattern', 'const { h: [{ i }] } = { h: [{ i: b }] }; sink(i)'), ('a rest in a pattern', 'const { skip, ...rest } = { skip: 1, held: b }; sink(rest.held)'), ('a default parameter', '((p = b) => sink(p))()'),
 ('entries, keys, values of an array', 'for (const [, x] of [b].entries()) sink(x); for (const x of [b].values()) sink(x)'), ('for of', 'for (const x of [b]) sink(x)'), ('for in and a computed key', 'const h = { held: b }; for (const key in h) sink(h[key])'),
 ('a Map', 'sink(new Map([["k", b]]).get("k"))'), ('a Map as the key', 'sink([...new Map([[b, 1]]).keys()][0])'), ('Map.forEach', 'new Map([["k", b]]).forEach(x => sink(x))'), ('Map entries', 'for (const [, x] of new Map([["k", b]])) sink(x)'), ('a Set', 'for (const x of new Set([b])) sink(x)'), ('Set.forEach', 'new Set([b]).forEach(x => sink(x))'), ('a WeakMap', 'const key = {}; sink(new WeakMap([[key, b]]).get(key))'), ('a WeakRef', 'sink(new WeakRef(b).deref())'), ('Map.groupBy, Object.groupBy', 'sink(Map.groupBy([b], () => "g").get("g")[0]); sink(Object.groupBy([b], () => "g").g[0])'),
 ('a member of a literal', 'sink({ held: b }.held)'), ('a computed member', 'const key = ["he", "ld"].join(""); sink({ [key]: b }[key])'), ('stored by a computed key', 'const h = {}; h[["he", "ld"].join("")] = b; sink(h.held)'), ('Object.values, entries', 'sink(Object.values({ held: b })[0]); sink(Object.entries({ held: b })[0][1])'), ('Object.fromEntries', 'sink(Object.fromEntries([["held", b]]).held)'),
 ('Object.assign carries it', 'sink(Object.assign({}, { held: b }).held)'), ('Object.assign returns it', 'sink(Object.assign(b, {}))'), ('a spread carries it', 'sink({ ...{ held: b } }.held)'), ('Object.create, inherited', 'sink(Object.create({ held: b }).held)'), ('Object.create with descriptors', 'sink(Object.create(null, { held: { value: b } }).held)'), ('defineProperty: a value', 'sink(Object.defineProperty({}, "held", { value: b }).held)'), ('defineProperty: a getter', 'sink(Object.defineProperty({}, "held", { get: () => b }).held)'), ('a getter in a literal', 'sink({ get held() { return b; } }.held)'), ('a setter receives it', '({ set held(x) { sink(x); } }).held = b'),
 ('getOwnPropertyDescriptor', 'sink(Object.getOwnPropertyDescriptor({ held: b }, "held").value)'), ('freeze, seal, preventExtensions return it', 'sink(Object.freeze(b))'), ('Reflect.get', 'sink(Reflect.get({ held: b }, "held"))'), ('Reflect.set', 'const h = {}; Reflect.set(h, "held", b); sink(h.held)'), ('Reflect.apply', 'Reflect.apply(sink, null, [b])'), ('Reflect.construct', 'Reflect.construct(function (x) { sink(x); }, [b])'), ('Reflect.get with a receiver', 'sink(Reflect.get({ get me() { return this; } }, "me", b))'),
 ('call', 'sink.call(null, b)'), ('apply', 'sink.apply(null, [b])'), ('bind', 'sink.bind(null, b)()'), ('bind: this', '(function () { sink(this); }).bind(b)()'), ('call: this', '(function () { sink(this); }).call(b)'), ('a method: this', 'b.go = function () { sink(this); }; b.go(); delete b.go'), ('a closure', '(() => () => sink(b))()()'), ('a closure over a variable stored later', 'let v = null; const f = () => sink(v); v = b; f()'),
 ('returned by a function', 'sink((() => b)())'), ('?: && || ?? and the comma', 'sink(b.x$ === undefined ? b : b); sink(1 && b); sink(0 || b); sink(null ?? b); sink((0, b))'), ('a logical assignment', 'let v = null; v ??= b; sink(v); let w = 0; w ||= b; sink(w)'), ('thrown and caught', 'try { throw b; } catch (e) { sink(e); }'), ('thrown through a function', 'try { (() => { throw b; })(); } catch (e) { sink(e); }'), ('returned by finally', 'sink((() => { try { return 1; } finally { return b; } })())'),
 ('a generator yields it', 'sink((function* () { yield b; })().next().value)'), ('a generator returns it', 'sink((function* () { return b; })().next().value)'), ('sent into a generator', 'const g = (function* () { sink(yield 1); })(); g.next(); g.next(b)'), ('thrown into a generator', 'const g = (function* () { try { yield 1; } catch (e) { sink(e); } })(); g.next(); g.throw(b)'), ('return() of a generator', 'const g = (function* () { yield 1; })(); g.next(); sink(g.return(b).value)'), ('yield*', 'sink((function* () { yield* [b]; })().next().value)'), ('an iterator of my own', 'for (const x of { [Symbol.iterator]() { let n = 0; return { next: () => (n++ ? { done: true, value: undefined } : { done: false, value: b }) }; } }) sink(x)'),
 ('a class field', 'sink(new (class { held = b; })().held)'), ('a constructor stores it', 'sink(new (class { constructor(x) { this.held = x; } })(b).held)'), ('a constructor returns it', 'sink(new (class { constructor() { return b; } })())'), ('a private field', 'sink(new (class { #h = b; get() { return this.#h; } })().get())'), ('a static field, a static block', 'sink((class { static held = b; }).held); (class { static { sink(b); } })'), ('super', 'sink(new (class extends (class { get() { return b; } }) { get() { return super.get(); } })().get())'), ('an accessor of a class', 'sink(new (class { get held() { return b; } })().held)'),
 ('a proxy around it', 'sink(new Proxy(b, {}))'), ('the get trap yields it', 'sink(new Proxy({}, { get: () => b }).whatever)'), ('the trap receives it as the target', 'new Proxy(b, { get: (t) => (sink(t), 1) }).x'), ('the set trap receives it', 'new Proxy({}, { set: (t, k, v) => (sink(v), true) }).x = b'), ('the apply trap', 'new Proxy(() => 0, { apply: (t, self, args) => sink(args[0]) })(b)'),
 ('JSON.stringify: toJSON sees it as this', 'b.toJSON = function () { sink(this); return 1; }; JSON.stringify(b); delete b.toJSON'), ('JSON.stringify: the replacer', 'JSON.stringify({ held: b }, (key, v) => (key === "held" && sink(v), v))'), ('JSON.stringify: the replacer, this', 'JSON.stringify(b, function (key, v) { if (key !== "") sink(this); return typeof v === "object" && key !== "" ? 0 : v; })'), ('JSON.parse makes one like it', 'sink(JSON.parse(JSON.stringify(b)))'), ('JSON.parse: the reviver', 'JSON.parse("[1]", function (key, v) { return key === "0" ? (sink(b), v) : v; })'),
 ('a tagged template', '((strings, x) => sink(x))`a${b}c`'), ('String.replace with a function', '"a".replace("a", () => (sink(b), ""))'), ('a conversion: valueOf sees it as this', 'b.valueOf = function () { sink(this); return 1; }; +b; delete b.valueOf'), ('a conversion: Symbol.toPrimitive', 'b[Symbol.toPrimitive] = function () { sink(this); return 1; }; `${b}`; delete b[Symbol.toPrimitive]'),
 ('globalThis', 'globalThis.held$ = b; sink(globalThis.held$); delete globalThis.held$'), ('a symbol as the key', 'const s = Symbol(); sink({ [s]: b }[s])'), ('a number as the key', 'sink({ 7: b }[7]); sink({ 7: b }["7"])'), ('optional chaining', 'sink({ h: { i: b } }?.h?.i); sink((() => b)?.())'), ('Object(b)', 'sink(Object(b))'), ('new Object(b)', 'sink(new Object(b))'), ('structured by hand', 'const c = {}; for (const key of Object.keys(b)) c[key] = b[key]; sink(c)'), ('in the opposite order by hand', 'const c = {}; for (const key of Object.keys(b).reverse()) c[key] = b[key]; sink(c)'),
]
LATER = [
 ('await', 'sink(await b)'), ('await a promise', 'sink(await Promise.resolve(b))'), ('then', 'await Promise.resolve(b).then(x => sink(x))'), ('a rejection', 'await Promise.reject(b).catch(e => sink(e))'), ('await of a rejection', 'try { await Promise.reject(b); } catch (e) { sink(e); }'), ('new Promise', 'sink(await new Promise(ok => ok(b)))'), ('a thenable', 'sink(await { then(ok) { ok(b); } })'),
 ('Promise.all', 'sink((await Promise.all([b]))[0])'), ('Promise.allSettled', 'sink((await Promise.allSettled([b]))[0].value); sink((await Promise.allSettled([Promise.reject(b)]))[0].reason)'), ('Promise.race, any', 'sink(await Promise.race([b])); sink(await Promise.any([b]))'), ('Promise.any: the errors', 'try { await Promise.any([Promise.reject(b)]); } catch (e) { sink(e.errors[0]); }'), ('finally passes it on', 'sink(await Promise.resolve(b).finally(() => 1))'), ('withResolvers', 'const w = Promise.withResolvers(); w.resolve(b); sink(await w.promise)'),
 ('an async function returns it', 'sink(await (async () => b)())'), ('an async generator', 'for await (const x of (async function* () { yield b; })()) sink(x)'), ('for await over an array', 'for await (const x of [b]) sink(x)'), ('Array.fromAsync', 'sink((await Array.fromAsync([b]))[0])'),
]
A = (lambda s: s) if not ts else (lambda s: s)
out = []
if ts: out.append('declare const console: { log(...values: unknown[]): void };\n')
out.append('const show = (v%s) => (v === null ? "null" : typeof v === "object" ? (Array.isArray(v) ? "[" + v.join() + "]" : "{" + Object.keys(v).join() + "}") : typeof v + ":" + String(v));\n' % (': any' if ts else ''))
n = 0
def row(what, body, later):
    global n
    n += 1
    t = ': any' if ts else ''
    if calls:
        kinds = ['(p, q) => "B" + p + q + k', 'function (p) { return "B" + p + arguments.length + k; }', '((p, q, r) => "B" + p + q + r + k).bind(null, 7)', 'Math.max', 'new Proxy((p) => "B" + p + k, {})', 'async (p) => "B" + p', 'function* (p) { yield p; }', 'class { constructor(p) { this.p = p; } }', '({ m(p) { return "B" + p + k; } }).m', 'String', '(p = 5, ...rest) => "B" + p + rest.length + k', 'Object.assign((p) => "B" + p + k, { tag: 1 })']
        if lean:
            kinds = ['(p, q) => "B" + p + q + k', 'function (p) { return "B" + p + arguments.length + k; }', '({ m(p) { return "B" + p + k; } }).m', '(p = 5, ...rest) => "B" + p + rest.length + k', 'function named(p, q) { return "B" + q + p + k; }']
            s = 'function read$(f) { return f(1, 2); }\n'
            s += '%sfunction row$() { const k = $; let got = ""; const sink = f => { got += read$(f) + " "; }; const a = (p, q) => "A" + p + q + k; sink(a); sink(a); const b = %s; %s; sink(a); return got; }\n' % ('async ' if later else '', kinds[(n + shift) % len(kinds)], body)
            s += '{ let text; try { text = %srow$(); } catch { text = "THROWS"; } console.log("%d %s: " + text); }\n' % ('await ' if later else '', n, what.replace('"', "'"))
            out.append(s.replace('${', '\x00').replace('$', str(n)).replace('\x00', '${'))
            return
        s = 'function read$(f%s) { return show(f(1, 2)); }\n' % t
        s += '%sfunction row$() { const k = $; const got%s = []; const sink = (f%s) => { try { got.push(read$(f)); } catch (e) { got.push("T:" + e.name); } }; const a%s = (p, q) => "A" + p + q + k; sink(a); sink(a); const b%s = %s; try { %s; } catch (e) { got.push("THROWS " + (e && e.name)); } sink(a); return got.join(" "); }\n' % ('async ' if later else '', '', t, t, t, kinds[(n + shift) % len(kinds)], body)
    else:
      s = 'function read$(o%s) { return show(o.x$) + show(o.y$) + show(o.z$) + show(o.w$); }\n' % t
      s += '%sfunction row$() { const got%s = []; const sink = (o%s) => { got.push(read$(o)); }; const a%s = { x$: 1, y$: "a", z$: [1] }; sink(a); sink({ x$: 2, y$: "b", z$: [2] }); const b%s = { w$: { deep: 1 }, z$: "zed", x$: "ex", v$: 0 }; try { %s; } catch (e) { got.push("THROWS " + (e && e.name)); } sink(a); return got.join(" "); }\n' % ('async ' if later else '', ': string[]' if ts else '', t, t, t, body)
    s += 'console.log("%d %s: " + %srow$());\n' % (n, what.replace('"', "'"), 'await ' if later else '')
    out.append(s.replace('${', '\x00').replace('$', str(n)).replace('\x00', '${'))
for what, body in ROADS: row(what, body, False)
for what, body in LATER: row(what, body, True)
print(''.join(out), end='')
